(function(root){let token='',available=false,voice=false,seq=0,controller=null,audio=null;const A={enabled:false,async status(){if(location.protocol==='file:')return {mode:'mock',voice:'mock'};try{const r=await fetch('/api/status');const d=await r.json();token=d.csrf||'';available=d.mode==='available';voice=d.voice==='available';return d}catch{return {mode:'mock',voice:'mock'}}},cancel(){seq++;controller?.abort();controller=null;audio?.pause?.();audio=null;},async request(kind,data,key){if(!A.enabled||!available)return null;A.cancel();const generation=seq;controller=new AbortController();try{const r=await fetch('/api/'+kind,{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json','x-csrf-token':token,'idempotency-key':key},body:JSON.stringify({...data,consent:true}),signal:controller.signal});if(!r.ok)return null;const d=await r.json();return generation===seq&&d.mode==='ai'?d.result:null}catch{return null}finally{if(generation===seq)controller=null}},async speak(role,text){if(!A.enabled||!voice||!text)return false;try{const r=await fetch('/api/voice',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json','x-csrf-token':token,'idempotency-key':'voice-'+Date.now()},body:JSON.stringify({role,text,consent:true})});if(!r.ok||!r.headers.get('content-type')?.startsWith('audio/'))return false;const url=URL.createObjectURL(await r.blob());audio=new Audio(url);audio.onended=()=>URL.revokeObjectURL(url);await audio.play();return true}catch{return false}},get available(){return available}};root.PandaAI=A;})(window);
